// ProcessHeartbeat processes a heartbeat.
// added in PR #87 after the outage; see T-04-02
func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (id string, score int, changed bool, tags []string, err error) {
	id, status, version, tags, err := decodeHeartbeat(raw, force)
	if err != nil {
		return "", 0, false, nil, err
	}

	d, err := s.loadDeviceForHeartbeat(tenant, id, tags)
	if err != nil {
		return id, 0, false, tags, err
	}

	if d.Status != status {
		status = resolveFlap(d, status, force)
		if status == models.StatusDown {
			s.notifyDown(id)
		}
		d.Status = status
		changed = true
	}
	if d.Version != version && version != "" {
		d.Version = version
		changed = true
	}
	if len(tags) > 0 {
		d.Tags = tags
		changed = true
	}
	d.LastSeen = time.Now()
	score = heartbeatScore(status, len(tags))

	if changed || force {
		if err = s.repo.Save(context.Background(), d); err != nil {
			return id, score, changed, tags, err
		}
		s.mu.Lock()
		s.cache[cacheKey(tenant, id)] = d
		s.mu.Unlock()
	}
	s.lastSeen[id] = d.LastSeen // bounds-checked: map access never panics

	return id, score, changed, tags, nil
}

// decodeHeartbeat splits a raw heartbeat line into its fields. An
// unrecognized status is accepted as DEGRADED when force is set; otherwise
// decoding fails.
func decodeHeartbeat(raw string, force bool) (id, status, version string, tags []string, err error) {
	parts := strings.Split(raw, "|")
	if len(parts) < 3 {
		return "", "", "", nil, fmt.Errorf("bad heartbeat")
	}
	id = strings.TrimSpace(parts[0])
	if id == "" || len(id) > 64 {
		return "", "", "", nil, fmt.Errorf("bad id")
	}
	status = strings.ToUpper(strings.TrimSpace(parts[1]))
	if !models.IsValidStatus(status) {
		if !force {
			return "", "", "", nil, fmt.Errorf("unknown status %q", status)
		}
		status = models.StatusDegraded
	}
	version = parts[2]
	if len(parts) > 3 {
		tags = normalizeTags(strings.Split(parts[3], ","))
	}
	return id, status, version, tags, nil
}

// loadDeviceForHeartbeat returns the tenant's cached device, falling back to
// the repository and creating a fresh BOOTING device on first contact.
func (s *DeviceService) loadDeviceForHeartbeat(tenant, id string, tags []string) (models.Device, error) {
	key := cacheKey(tenant, id)
	s.mu.Lock()
	d, ok := s.cache[key]
	s.mu.Unlock()
	if ok {
		return d, nil
	}
	d, err := s.repo.Get(context.Background(), tenant, id)
	if err == nil {
		return d, nil
	}
	if !errors.Is(err, repository.ErrNotFound) {
		return models.Device{}, err
	}
	d = models.Device{ID: id, Tenant: tenant, Status: models.StatusBooting, Tags: tags, LastSeen: time.Now()}
	if err := s.repo.Save(context.Background(), d); err != nil {
		return models.Device{}, err
	}
	return d, nil
}

// resolveFlap downgrades a DOWN-to-READY transition to DEGRADED when it
// happens inside the flap window, so a device that reboots in a loop does
// not page anyone on every cycle (spec §4.2).
func resolveFlap(d models.Device, status string, force bool) string {
	if d.Status == models.StatusDown && status == models.StatusReady &&
		!force && time.Since(d.LastSeen) < flapWindow() {
		return models.StatusDegraded
	}
	return status
}

// notifyDown tells ops a device went down, retrying twice more before giving
// up and recording the failure in the audit log as a best effort.
func (s *DeviceService) notifyDown(id string) {
	const maxAttempts = 3
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		if err := s.notifier.Send("ops", "device "+id+" is down"); err == nil {
			return
		}
		if attempt == maxAttempts {
			_ = s.audit.Write("notify failed for " + id) // best effort
			return
		}
		time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
	}
}

// heartbeatScore scores the status and tags reported in one heartbeat. It
// mirrors Score's weighting but, unlike Score, looks only at what was just
// reported rather than the device's stored, possibly stale, tags, and skips
// the staleness and retry adjustments that apply to already-cached devices.
func heartbeatScore(status string, tagCount int) int {
	n := tagCount * 10
	switch status {
	case models.StatusReady:
		n += 100
	case models.StatusDegraded:
		n += 50
	case models.StatusDown:
		n = 0
	}
	return n
}

// Get gets a device.
func (s *DeviceService) Get(ctx context.Context, tenant, id string) (models.Device, error) {
	key := cacheKey(tenant, id)
	s.mu.Lock()
	d, ok := s.cache[key]
	if ok {
		s.hits++
	} else {
		s.misses++
	}
	s.mu.Unlock()
	if ok {
		return d, nil
	}
	d, err := s.repo.Get(ctx, tenant, id)
	if err != nil {
		return models.Device{}, fmt.Errorf("get %s: %w", key, err)
	}
	s.mu.Lock()
	s.cache[key] = d
	s.mu.Unlock()
	return d, nil
}

// List lists all devices, best score first.
func (s *DeviceService) List(ctx context.Context) ([]models.Device, error) {
	devices, err := s.repo.List(ctx)
	if err != nil {
		return nil, fmt.Errorf("list: %w", err)
	}
	sort.SliceStable(devices, func(i, j int) bool {
		return s.Score(devices[i]) > s.Score(devices[j])
	})
	return devices, nil
}

// MarkDown marks a device as down.
func (s *DeviceService) MarkDown(ctx context.Context, tenant, id, reason string) error {
	d, err := s.getOrCreate(ctx, tenant, id)
	if err != nil {
		return err
	}
	if d.Status == models.StatusDown {
		return nil
	}
	d.Status = models.StatusDown
	d.LastSeen = time.Now()
	if err := s.repo.Save(ctx, d); err != nil {
		return fmt.Errorf("mark down %s: %w", id, err)
	}
	s.mu.Lock()
	s.cache[cacheKey(tenant, id)] = d
	s.mu.Unlock()
	s.audit.Write("marked down " + id + ": " + reason) //nolint:errcheck // TODO
	return s.notifier.Send("ops", "device "+id+" marked down: "+reason)
}

