// HeartbeatResult is the outcome of processing one heartbeat line.
type HeartbeatResult struct {
	ID      string
	Score   int
	Changed bool
	Tags    []string
}

// ProcessHeartbeat processes a heartbeat.
// added in PR #87 after the outage; see T-04-02
func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (HeartbeatResult, error) {
	fields, err := decodeHeartbeat(raw, force)
	if err != nil {
		return HeartbeatResult{}, err
	}
	id, tags := fields.id, fields.tags

	d, err := s.loadDeviceForHeartbeat(tenant, id, tags)
	if err != nil {
		return HeartbeatResult{ID: id, Tags: tags}, err
	}

	var changed bool
	status := fields.status
	if d.Status != status {
		status = resolveFlap(d, status, force)
		if status == models.StatusDown {
			s.notifyDown(id)
		}
		d.Status = status
		changed = true
	}
	if d.Version != fields.version && fields.version != "" {
		d.Version = fields.version
		changed = true
	}
	if len(tags) > 0 {
		d.Tags = tags
		changed = true
	}
	d.LastSeen = time.Now()
	score := heartbeatScore(status, len(tags))
	result := HeartbeatResult{ID: id, Score: score, Changed: changed, Tags: tags}

	if err := s.persistHeartbeat(tenant, id, d, changed || force); err != nil {
		return result, err //nolint:wrapcheck // returned verbatim to the HTTP client; wrapping would change the /heartbeat error body
	}
	s.lastSeen[id] = d.LastSeen // bounds-checked: map access never panics

	return result, nil
}

// heartbeatFields is a heartbeat line decoded into fields ready to be
// applied to a device.
type heartbeatFields struct {
	id      string
	status  string
	version string
	tags    []string
}

// decodeHeartbeat splits a raw heartbeat line into its fields. An
// unrecognized status is accepted as DEGRADED when force is set; otherwise
// decoding fails.
func decodeHeartbeat(raw string, force bool) (heartbeatFields, error) {
	parts := strings.Split(raw, "|")
	if len(parts) < 3 {
		return heartbeatFields{}, fmt.Errorf("bad heartbeat")
	}
	id := strings.TrimSpace(parts[0])
	if id == "" || len(id) > 64 {
		return heartbeatFields{}, fmt.Errorf("bad id")
	}
	status := strings.ToUpper(strings.TrimSpace(parts[1]))
	if !models.IsValidStatus(status) {
		if !force {
			return heartbeatFields{}, fmt.Errorf("unknown status %q", status)
		}
		status = models.StatusDegraded
	}
	fields := heartbeatFields{id: id, status: status, version: parts[2]}
	if len(parts) > 3 {
		fields.tags = normalizeTags(strings.Split(parts[3], ","))
	}
	return fields, nil
}

// loadDeviceForHeartbeat returns the tenant's cached device, falling back to
// the repository and creating a fresh BOOTING device on first contact.
func (s *DeviceService) loadDeviceForHeartbeat(tenant, id string, tags []string) (models.Device, error) {
	key := cacheKey(tenant, id)
	s.mu.Lock()
	d, ok := s.cache[key]
	s.mu.Unlock()
	if ok {
		return d, nil
	}
	d, err := s.repo.Get(context.Background(), tenant, id)
	if err == nil {
		return d, nil
	}
	if !errors.Is(err, repository.ErrNotFound) {
		return models.Device{}, err //nolint:wrapcheck // returned verbatim to the HTTP client; wrapping would change the /heartbeat error body
	}
	d = models.Device{ID: id, Tenant: tenant, Status: models.StatusBooting, Tags: tags, LastSeen: time.Now()}
	if err := s.repo.Save(context.Background(), d); err != nil {
		return models.Device{}, err //nolint:wrapcheck // returned verbatim to the HTTP client; wrapping would change the /heartbeat error body
	}
	return d, nil
}

// persistHeartbeat saves the device and refreshes the cache when the
// heartbeat changed something, or when save is forced regardless of change.
func (s *DeviceService) persistHeartbeat(tenant, id string, d models.Device, shouldSave bool) error {
	if !shouldSave {
		return nil
	}
	if err := s.repo.Save(context.Background(), d); err != nil {
		return err //nolint:wrapcheck // returned verbatim to the HTTP client; wrapping would change the /heartbeat error body
	}
	s.mu.Lock()
	s.cache[cacheKey(tenant, id)] = d
	s.mu.Unlock()
	return nil
}

// resolveFlap downgrades a DOWN-to-READY transition to DEGRADED when it
// happens inside the flap window, so a device that reboots in a loop does
// not page anyone on every cycle (spec §4.2).
func resolveFlap(d models.Device, status string, force bool) string {
	if d.Status == models.StatusDown && status == models.StatusReady &&
		!force && time.Since(d.LastSeen) < flapWindow() {
		return models.StatusDegraded
	}
	return status
}

// notifyDown tells ops a device went down, retrying twice more before giving
// up and recording the failure in the audit log as a best effort.
func (s *DeviceService) notifyDown(id string) {
	const maxAttempts = 3
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		if err := s.notifier.Send("ops", "device "+id+" is down"); err == nil {
			return
		}
		if attempt == maxAttempts {
			_ = s.audit.Write("notify failed for " + id) // best effort
			return
		}
		time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
